    'A': 1, 'NS': 2, 'CNAME': 5, 'SOA': 6, 'PTR': 12, 'HINFO': 13,
    'MX': 15, 'TXT': 16, 'AAAA': 28, 'SRV': 33, 'NAPTR': 35,
    'OPT': 41, 'DS': 43, 'SSHFP': 44, 'TLSA': 52, 'CAA': 257,
}
TYPE_VALUES = {v: k for k, v in TYPES.items()}

def get_type_name(t): return TYPE_VALUES.get(t, str(t))
def get_class_name(c): return CLASS_VALUES.get(c, str(c))

# Colors
COLOR_RESET = "\033[0m"
COLOR_BOLD_GREEN = "\033[1;32m"
COLOR_BOLD_BLUE = "\033[1;34m"
COLOR_CYAN = "\033[36m"
COLOR_YELLOW = "\033[33m"
