        self.authorities = parse_rr(ns)
        self.additionals = parse_rr(ar)

    def parse_rdata(self, rtype, rdata, packet_data, offset):
        if rtype == 1: return {"address": socket.inet_ntop(socket.AF_INET, rdata)}
        if rtype == 28: return {"address": socket.inet_ntop(socket.AF_INET6, rdata)}
        if rtype in [2, 5, 12]:
            name, _ = self.decode_name(packet_data, offset)
            return {{5: "cname", 2: "nameserver", 12: "ptrname"}[rtype]: name}
        if rtype == 15:
            pref = struct.unpack(">H", rdata[:2])[0]
            name, _ = self.decode_name(packet_data, offset + 2)
            return {"preference": pref, "exchange": name}
        if rtype == 16:
            msgs, o = [], 0
            while o < len(rdata):
                l = rdata[o]; msgs.append(rdata[o+1:o+1+l].decode(errors='replace')); o += 1 + l
            return {"messages": msgs}
        if rtype == 6:
            mname, next_o = self.decode_name(packet_data, offset)
            rname, next_o = self.decode_name(packet_data, next_o)
            s, re, rt, ex, mi = struct.unpack(">IIIII", packet_data[next_o:next_o+20])
            return {"mname": mname, "rname": rname, "serial": s, "refresh": re, "retry": rt, "expire": ex, "minimum": mi}
        if rtype == 33:
            p, w, po = struct.unpack(">HHH", rdata[:6])
            t, _ = self.decode_name(packet_data, offset + 6)
            return {"priority": p, "weight": w, "port": po, "target": t}
        if rtype == 257:
            f, tl = rdata[0], rdata[1]
            return {"critical": bool(f & 128), "tag": rdata[2:2+tl].decode(errors='replace'), "value": rdata[2+tl:].decode(errors='replace')}
        if rtype == 44:
            a, f = struct.unpack("BB", rdata[:2])
            return {"algorithm": a, "fingerprint_type": f, "fingerprint": rdata[2:].hex()}
        return {"raw": rdata.hex()}

def get_status_name(status):
    return {0: "NoError", 1: "FormErr", 2: "ServFail", 3: "NXDomain", 4: "NotImp", 5: "Refused"}.get(status, f"Error {status}")

def print_help():
    print("""dog ● command-line DNS client

Usage:
  dog [OPTIONS] [--] <arguments>

Examples:
  dog example.net                          Query a domain using default settings
  dog example.net MX                       ...looking up MX records instead
  dog example.net MX @1.1.1.1              ...using a specific nameserver instead
  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP
  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments

Query options:
  <arguments>              Human-readable host names, nameservers, types, or classes
  -q, --query=HOST         Host name or domain name to query
  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)
  -n, --nameserver=ADDR    Address of the nameserver to send packets to
  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)

Sending options:
  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)
  --txid=NUMBER            Set the transaction ID to a specific value
  -Z=TWEAKS                Set uncommon protocol-level tweaks

Protocol options:
  -U, --udp                Use the DNS protocol over UDP
  -T, --tcp                Use the DNS protocol over TCP
  -S, --tls                Use the DNS-over-TLS protocol
  -H, --https              Use the DNS-over-HTTPS protocol

Output options:
  -1, --short              Short mode: display nothing but the first result
  -J, --json               Display the output as JSON
  --color, --colour=WHEN   When to colourise the output (always, automatic, never)
  --seconds                Do not format durations, display them as seconds
  --time                   Print how long the response took to arrive

Meta options:
  -?, --help               Print list of command-line options
  -v, --version            Print version information""")

def format_record_data(rtype, data):
    if rtype in ['A', 'AAAA']: return data['address']
    if rtype == 'NS': return f"\"{data['nameserver']}\""
    if rtype == 'CNAME': return f"\"{data['cname']}\""
    if rtype == 'PTR': return f"\"{data['ptrname']}\""
    if rtype == 'MX': return f"{data['preference']} \"{data['exchange']}\""
    if rtype == 'TXT': return " ".join(f"\"{m}\"" for m in data['messages'])
    if rtype == 'SOA':
        return f"\"{data['mname']}\" \"{data['rname']}\" {data['serial']} {format_duration(data['refresh'])} {format_duration(data['retry'])} {format_duration(data['expire'])} {format_duration(data['minimum'])}"
    if rtype == 'SRV': return f"{data['priority']} {data['weight']} \"{data['target']}\":{data['port']}"
    if rtype == 'CAA': return f"\"{data['tag']}\" \"{data['value']}\" ({'critical' if data['critical'] else 'non-critical'})"
    if rtype == 'HINFO': return f"\"{data['cpu']}\" \"{data['os']}\""
    return str(data)

def main():
    args = sys.argv[1:]
    if not args or '-?' in args or '--help' in args: print_help(); sys.exit(3 if not args else 0)
    if '-v' in args or '--version' in args:
        print("dog ● command-line DNS client\nv0.2.0-pre [d3a34280] built on 2026-04-17 (pre-release!)\nhttps://dns.lookup.dog/"); sys.exit(0)

    domains, types, nameservers, classes = [], [], [], []
    use_udp, use_tcp, use_tls, use_https = False, False, False, False
    short_mode, json_mode, color_when = False, False, "automatic"
    use_seconds, measure_time = False, False
    edns, txid, tweaks = "hide", None, {'aa': False, 'ad': False, 'cd': False, 'bufsize': 4096}

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--': domains.extend(args[i+1:]); break
        elif arg.startswith('-q'): domains.append(arg[2:] if len(arg)>2 else args[i+1]); i += (1 if len(arg)>2 else 2)
        elif arg.startswith('--query='): domains.append(arg.split('=')[1]); i += 1
        elif arg == '--query': domains.append(args[i+1]); i += 2
        elif arg.startswith('-t'): types.append(arg[2:].upper() if len(arg)>2 else args[i+1].upper()); i += (1 if len(arg)>2 else 2)
        elif arg.startswith('--type='): types.append(arg.split('=')[1].upper()); i += 1
        elif arg == '--type': types.append(args[i+1].upper()); i += 2
        elif arg.startswith('-n'): nameservers.append(arg[2:] if len(arg)>2 else args[i+1]); i += (1 if len(arg)>2 else 2)
        elif arg.startswith('--nameserver='): nameservers.append(arg.split('=')[1]); i += 1
        elif arg == '--nameserver': nameservers.append(args[i+1]); i += 2
        elif arg.startswith('--class='): classes.append(arg.split('=')[1].upper()); i += 1
        elif arg == '--class': classes.append(args[i+1].upper()); i += 2
        elif arg in ['-U', '--udp']: use_udp = True; i += 1
        elif arg in ['-T', '--tcp']: use_tcp = True; i += 1
        elif arg in ['-S', '--tls']: use_tls = True; i += 1
        elif arg in ['-H', '--https']: use_https = True; i += 1
        elif arg in ['-1', '--short']: short_mode = True; i += 1
        elif arg in ['-J', '--json']: json_mode = True; i += 1
        elif arg.startswith('--color=') or arg.startswith('--colour='): color_when = arg.split('=')[1]; i += 1
        elif arg in ['--color', '--colour']: color_when = args[i+1]; i += 2
        elif arg == '--seconds': use_seconds = True; i += 1
        elif arg == '--time': measure_time = True; i += 1
        elif arg.startswith('--edns='): edns = arg.split('=')[1]; i += 1
        elif arg == '--edns': edns = args[i+1]; i += 2
        elif arg.startswith('--txid='): txid = int(arg.split('=')[1]); i += 1
        elif arg == '--txid': txid = int(args[i+1]); i += 2
        elif arg.startswith('-Z'):
            tw_list = arg[3:] if arg.startswith('-Z=') else (args[i+1] if arg == '-Z' else arg[2:])
            for tw in tw_list.split(','):
                if tw in ['aa', 'ad', 'cd']: tweaks[tw] = True
                elif tw.startswith('bufsize='): tweaks['bufsize'] = int(tw.split('=')[1])
            i += (2 if arg == '-Z' else 1)
        elif arg.startswith('-'): print(f"dog: Invalid options: Unrecognized option: '{arg.lstrip('-')}'"); sys.exit(3)
        else:
            if arg.startswith('@'): nameservers.append(arg[1:])
            elif arg.upper() in TYPES: types.append(arg.upper())
            elif arg.upper() in CLASSES: classes.append(arg.upper())
            else: domains.append(arg)
            i += 1

    if not domains: print_help(); sys.exit(3)
    if not types: types = ['A']
    if not classes: classes = ['IN']
    if not nameservers:
        ns = get_system_nameserver()
        if not ns: sys.exit(4)
        nameservers = [ns]

    use_color = color_when == "always" or (color_when != "never" and sys.stdout.isatty())
    start_t = time.time()
    resps = []
    for domain in domains:
        for dt in types:
            for dc in classes:
                for ns in nameservers:
                    p = DNSPacket(txid=txid)
                    p.add_query(domain, TYPES[dt], CLASSES[dc])
                    if tweaks['aa']: p.flags |= 0x0400
                    if tweaks['ad']: p.flags |= 0x0020
                    if tweaks['cd']: p.flags |= 0x0010
                    try:
                        data = send_dns_query(p, ns, use_udp, use_tcp, use_tls, use_https, tweaks['bufsize'], edns)
                        p.parse_response(data); resps.append(p)
                    except Exception as e: print(f"Error [network]: {e}"); sys.exit(1)

    if json_mode:
        out = {"responses": []}
        for p in resps:
            r = {"queries": [{"name": (q['name'] if q['name'].endswith('.') else q['name'] + '.'), "class": get_class_name(q['class']), "type": get_type_name(q['type'])} for q in p.queries], "answers": [], "authorities": [], "additionals": []}
            for section, target in [('answers', p.answers), ('authorities', p.authorities), ('additionals', p.additionals)]:
                for rr in target:
                    if section == 'additionals' and rr['type'] == 'OPT': continue
                    d = rr['data'].copy()
                    if rr['type'] == 'SOA': d = {"mname": d['mname']}
                    elif rr['type'] == 'TXT': d = {"messages": d['messages']}
                    r[section].append({"name": rr['name'], "class": rr['class'], "ttl": rr['ttl'], "type": rr['type'], "data": d})
            out["responses"].append(r)
        print(json.dumps(out, separators=(',', ':')))
    elif short_mode:
        found = False
        for p in resps:
            for ans in p.answers: print(format_record_data(ans['type'], ans['data'])); found = True
        if not found:
            for p in resps:
                if p.status != 0: sys.exit(2)
    else:
        max_t = 0
        for p in resps:
            for rr in p.answers + p.authorities + (p.additionals if edns == "show" else []):
                max_t = max(max_t, len(rr['type']))
        for p in resps:
            if p.status != 0: print(f"Status: {get_status_name(p.status)}")
            for section, rr in [('ans', a) for a in p.answers] + [('auth', a) for a in p.authorities] + [('add', a) for a in p.additionals if edns == "show"]:
                t, n, ttl, d = rr['type'], rr['name'], format_duration(rr['ttl'], use_seconds), format_record_data(rr['type'], rr['data'])
                if t == 'OPT': print(f"OPT                   + 4096 0 0 0 []"); continue
                if not n.endswith('.'): n += '.'
                t_c = get_type_color(t) if use_color else ""
                n_c = COLOR_BOLD_BLUE if use_color else ""
                res = COLOR_RESET if use_color else ""
                m = (f"{COLOR_CYAN}A{res} " if use_color else "A ") if section == 'auth' else "  "
                print(f"{t_c}{t: >{max_t}}{res} {n_c}{n}{res} {ttl: >6} {m}{d}")
        if measure_time: print(f"Ran in {int((time.time()-start_t)*1000)}ms")

def get_system_nameserver():
    try:
        with open('/etc/resolv.conf') as f:
            for l in f:
                if l.startswith('nameserver'): return l.split()[1]
    except: pass
    return None

def send_dns_query(p, ns, use_udp, use_tcp, use_tls, use_https, bsize, edns):
    port = 53
    if '://' in ns:
        u = urlparse(ns)
        if u.scheme == 'https':
            m = p.build_packet(bsize if edns != "disable" else None)
            c = http.client.HTTPSConnection(u.netloc)
            c.request("POST", u.path + ("?" + u.query if u.query else ""), m, {"Content-Type": "application/dns-message", "Accept": "application/dns-message"})
            r = c.getresponse()
            if r.status != 200: raise Exception(f"HTTP {r.status}")
            return r.read()
    if ':' in ns and ('[' not in ns or ']:' in ns):
        ns, port = (ns.split(']:')[0]+']', int(ns.split(']:')[1])) if ']:' in ns else (ns.rsplit(':', 1)[0], int(ns.rsplit(':', 1)[1]))
    m = p.build_packet(bsize if edns != "disable" else None)
    if use_tls:
        if port == 53: port = 853
        with ssl.create_default_context().wrap_socket(socket.create_connection((ns, port)), server_hostname=ns) as s:
            s.send(struct.pack(">H", len(m)) + m); return s.read(struct.unpack(">H", s.read(2))[0])
    if use_tcp or len(m) > 512:
        with socket.create_connection((ns, port)) as s:
            s.send(struct.pack(">H", len(m)) + m); rl = struct.unpack(">H", s.recv(2))[0]
            d = b""; 
            while len(d) < rl: d += s.recv(rl - len(d))
            return d
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(5); s.sendto(m, (ns, port)); return s.recvfrom(4096)[0]

if __name__ == "__main__": main()
